"""按已核对的身份母版追加动作、退场与效果原稿，所有姿态继续使用同一参考。"""
from pathlib import Path
import argparse,json
from prepare_handpainted import STYLE,CUTOUT


def main():
 p=argparse.ArgumentParser();p.add_argument('--root',type=Path,required=True);args=p.parse_args();root=args.root
 jobs=json.loads((root/'requests.json').read_text());known={j['id'] for j in jobs}
 def add(id,prompt,refs,kind='sprite',width=768,height=768,**extra):
  if id not in known:
   jobs.append(dict(id=id,prompt=prompt,refs=refs,kind=kind,width=width,height=height,seed=244500+len(jobs)*37,**extra));known.add(id)
 add('unit-4-final','Edit this exact heavy halberd infantry illustration only. Remove the silver AXE BLADE at the BOTTOM end of the wooden shaft completely. The lower end is a plain rounded WOODEN shaft below the gripping hand, with no metal blade or spike. Keep ONE silver spear and side blade at the UPPER end above his helmet, broad bronze shoulders, older stern face and dark red heavy armor. Keep all other pixels, hand-painted linework, camera, green background and complete feet. No extra weapons.', ['generated/unit-4-corrected.png'],width=512,height=640,type=4)
 for city in ['capital','fort']:
  add('city-'+city+'-final','Edit this exact fortified city illustration. Cut a LARGE OPEN ARCHED GATE through the center of the FRONT OUTER WALL that is closest to the viewer. The arch starts at ground level and visibly leads into the courtyard. Add fitted gray arch stones and two open dark wooden gate leaves on its sides. The main gate must face OUT toward the viewer; it must not be hidden behind another wall. Keep the complete outer wall perimeter around the gate, towers, blue-gray tiled roofs, exact camera, compact layout, hand-painted details and uniform green background. No text, no symbols, no people, no floating door.', ['generated/city-'+city+'.png'],city=city)
 # 这些母版已检查过：武器、服饰和大面积阵营色各不相同。
 masters={0:'unit-0-corrected',1:'unit-1-corrected',2:'unit-2-base',3:'unit-3-base',4:'unit-4-final',5:'unit-5-corrected'}
 names=['mounted cavalry with red horse caparison and long cavalry spear','infantry spearman with ONE spear and ONE oval shield','archer with recurved bow and arrow quiver','wooden warship with a red canvas sail and tiny red sailor','broad-shouldered elite heavy soldier with ONE long halberd','robed military strategist with BLACK SCHOLAR CAP and white feather fan, no armor']
 actions=[
  ['standing mounted ready','horse taking one natural walking step with rider stable','rider drawing his spear back','rider thrusting his long spear to screen RIGHT','horse and rider recoiling from an impact','horse crouched low with rider slumped, no dismemberment'],
  ['upright ready with shield guarding','taking one walking step','pulling spear back behind shield','thrusting spear to screen RIGHT with shield retained','recoiling, knees bent and shield low','lying on side on the ground, spear and shield beside him'],
  ['upright ready holding bow','taking one walking step','drawing a single arrow to his cheek with bowstring under tension','releasing a single arrow to screen RIGHT, correct bow and two arms','recoiling with bow held low','lying on side on the ground with bow beside him'],
  ['upright calm sailing ready','slightly fluttering red sail and rowing oar','sailor aiming a small bow over the gunwale','sailor shooting an arrow to screen RIGHT from the intact boat','boat rocking slightly with red sail pulled sideways','boat tilted with mast leaning, the hull remains a complete boat'],
  ['upright heavy ready','taking one heavy walking step','raising his single long halberd back','swinging his single halberd toward screen RIGHT with a stable wide stance','heavy armored body recoiling with knees bent','lying on side on the ground, the one halberd beside him'],
  ['upright calm ready with white feather fan','taking a measured walking step','raising his white feather fan','gesturing his fan toward screen RIGHT, robes flowing modestly','recoiling, with fan held close to chest','lying on side on the ground, fan beside him'],
 ]
 for kind,master in masters.items():
  prompt=STYLE+'Use the EXACT same '+names[kind]+' from the reference in ALL SIX separate poses. Match his face, headwear, red outfit, weapon and proportions exactly. A production sprite sheet with EXACTLY THREE COLUMNS and TWO ROWS, all six equal cells, each figure fully contained in its cell with wide empty gaps. Each cell is 512x512. Read the cells from top left to bottom right: '+ '; '.join(f'cell {i+1}: {a}' for i,a in enumerate(actions[kind]))+'. All figures face screen RIGHT; only the pose changes. Same character scale and the SAME FEET/ground baseline within every cell; the lying pose stays near that baseline. Completely flat uniform bright green #00ff00 background throughout. No visible grid, no labels, no numbers, no words, no borders, no UI, no scenery, no floor, no overlapping characters or weapons between cells. No extra subjects.'
  add(f'unit-{kind}-actions',prompt,['generated/'+master+'.png'],kind='sheet',width=1536,height=1024,type=kind,columns=3,rows=2,poses=['idle','stride','windup','attack','hit','down'])
  if kind==3:
   stages=['boat upright with red sail','boat beginning to list and sail loosening','boat tilted further, mast leaning','boat low and tilted, red sail partly collapsed','boat hull low and sail folded down','boat almost horizontal and damaged, still the same wood hull and red canvas, no waves or water']
  elif kind==0:
   stages=['mounted horse and rider recoiling','horse bending knees, rider leaning forward','horse lowering to knees and rider losing balance','horse and rider collapsing together onto their side','horse resting on its side with rider slumped beside saddle','horse and rider lying quietly on their side at ground level, intact anatomy, no gore']
  else:
   stages=['recoiling from impact with knees slightly bent','kneeling on one knee, weapon lowered','both knees buckling, upper body pitching forward','catching ground with a hand, torso turning onto side','lying on side at ground level, weapon beside him','settled on the ground on his side, same full outfit and weapon, no gore']
  prompt=STYLE+'The exact SAME '+names[kind]+' as reference, in a continuous six-stage defeat sequence. Production sprite sheet, EXACTLY THREE COLUMNS and TWO ROWS with six equal 512x512 cells and large empty gaps. In reading order from top left: '+'; '.join(f'cell {i+1}: {a}' for i,a in enumerate(stages))+'. Keep the SAME camera, complete subject, red outfit, anatomy, face, weapon, scale and feet/ground baseline within each cell. Separate limbs bend at joints. All parts remain together, no floating body, no spinning cutout, no blood, no gore. Completely flat uniform bright green #00ff00 background. No floor, no shadows on background, no text, no numbers, no borders, no grid, no scenery, no extra figures. Each entire pose and weapon fits inside its own cell.'
  add(f'unit-{kind}-defeat',prompt,['generated/'+master+'.png'],kind='sheet',width=1536,height=1024,type=kind,columns=3,rows=2,frames=6)
 effect_specs=[('slash','one curved bright silver-gold sword slash sweep with several fine trailing brush strokes'),('impact','a small warm amber burst of impact sparks, fine bright center and short irregular sparks'),('fire','a compact swirling orange and golden fire plume'),('water','a compact blue-white splash and curling water spray'),('mist','a compact soft violet-blue mist swirl'),('level','a small warm gold luminous ring and several tiny upward glowing motes')]
 prompt='Fine hand-painted ancient Chinese strategy game special-effect sprites, soft luminous illustrated brushwork with dimensional light, matching the reference painting. A sheet of SIX separated effects, EXACTLY THREE columns and TWO rows, generous empty gaps. In reading order: '+'; '.join(s for k,s in effect_specs)+'. Each effect fully contained in its own equal cell. Completely flat bright green #00ff00 backdrop, no people, no weapons, no text, no labels, no grid, no scenery, no borders, no symbols.'
 add('effects-sheet',prompt,[],kind='sheet',width=1536,height=1024,columns=3,rows=2,effects=[k for k,s in effect_specs])
 add('terrain-camp-final','Edit this exact military encampment illustration: REMOVE THE HUMAN WARRIOR completely and restore the plain beige tent cloth behind him. Keep only the THREE canvas tents, wooden stakes, supply boxes and red pennant. Empty camp, absolutely NO PEOPLE, no faces, no arms, no legs, no armor. Keep the original complete tents, wooden details, fine painted shading, camera and pure flat bright green background. No lettering or symbols.', ['generated/terrain-camp.png'],terrain='camp')
 add('terrain-village-final','Edit this exact village illustration: REMOVE all loose SPEARS, pole weapons and detached tools lying in front of the three houses. The foreground outside the houses is completely empty flat bright green background. Keep only the three complete houses, their tiled roofs, timber beams, plaster walls, doors, windows, stairs and the one wooden ladder leaning against the right house. No people, no warriors, no weapons, no text. Preserve the same camera and detailed hand-painted style.', ['generated/terrain-village.png'],terrain='village')
 for name,subject in [('supplies','a tied tan cloth grain sack with golden rice ears and a small wooden supply box'),('sun','one warm golden sun disk with short rays'),('cloud','one soft layered pale blue-gray cloud'),('wind','three elegant curved pale wisps of wind'),('rain','one blue-gray rain cloud with several falling blue drops'),('fog','three low horizontal banks of soft pale gray fog')]:
  add('icon-'+name+'-final','Exactly one isolated game UI icon: '+subject+'. Detailed hand-painted natural fine outlines and soft volume shading, restrained colors, complete centered icon filling about seventy percent of the canvas. Uniform bright green #00ff00 background. NO PEOPLE, no characters, no human silhouette, no human faces, no body, no creatures, no buildings, no scenery, no text, no border, no UI panel, no extra objects, no watermark.', [],width=512,height=512,icon=name)
 (root/'requests.json').write_text(json.dumps(jobs,ensure_ascii=False,indent=2)+'\n')
 selection_path=root/'selection.json'
 selected=json.loads(selection_path.read_text()) if selection_path.exists() else {}
 defaults=dict(masters=masters,cities=dict(capital='city-capital-final',fort='city-fort-final',harbor='city-harbor'),icons={n:'icon-'+n+'-final' for n in ['supplies','sun','cloud','wind','rain','fog']},terrains={n:'terrain-'+n+('-final' if n in ['camp','village'] else '') for n in ['mountain','tree','village','camp']})
 for key,value in defaults.items():selected.setdefault(key,value)
 selection_path.write_text(json.dumps(selected,ensure_ascii=False,indent=2)+'\n')
 print('Prepared',len(jobs),'original and action jobs')

if __name__=='__main__':main()
